def to_float_tensor(numpy_array: np.ndarray) ->torch.Tensor:
    if numpy_array.ndim == 2:
        # HxW -> 1x1xHxW
        return torch.from_numpy(numpy_array).unsqueeze(0).unsqueeze(0).float()
    elif numpy_array.ndim == 3:
        # HxWxC -> 1xCxHxW
        return torch.from_numpy(numpy_array).permute(2, 0, 1).unsqueeze(0).float()
    elif numpy_array.ndim == 4:
        # NxHxWxC -> NxCxHxW
        return torch.from_numpy(numpy_array).permute(0, 3, 1, 2).float()
    else:
        raise NotImplementedError(
            "Unknown numpy array dimension of {}".format(numpy_array.ndim)
        )
